DO $$ declare v_candidate uuid; v_binding sourcecubes.cube_bindings%rowtype; r record; begin select id into v_candidate from ecology.ssr_anchor_candidate_registry where infrastructure_name='Norman Manley International Airport' and lower(w3w_address)='///thing.pace.eagle' limit 1; if v_candidate is not null then select * into v_binding from sourcecubes.resolve_candidate_cube(v_candidate,1); for r in select * from sourcecubes.vertical_evidence_observations where anchor_candidate_id=v_candidate loop perform sourcecubes.bind_cube_evidence(v_binding.cube_uid,case when r.provider_code like '%GEBCO%' or r.provider_code='OT-BATHY' then 'SEA' else 'LAND' end,'VERTICAL_EVIDENCE',r.provider_code,'sourcecubes','vertical_evidence_observations',r.observation_id::text,r.source_timestamp,'ANCHOR_CANDIDATE_DIRECT',r.evidence_reference,r.evidence_payload); end loop; end if; end $$;
